import React, { useEffect, useState } from "react";
import axios from "axios";
import "./Page.css";

function Internships() {
  const [jobs, setJobs] = useState([]);
  const [year, setYear] = useState("");
  const [branch, setBranch] = useState("");
  const [category, setCategory] = useState(""); // For Government vs Private
  const [loading, setLoading] = useState(true);

  // Initial Fetch: Get all jobs from the backend
  useEffect(() => {
    fetchJobs();
  }, []);

  const fetchJobs = () => {
    setLoading(true);
    axios.get("http://localhost:5000/api/jobs")
      .then(res => {
        // Filter locally for internships/fresher roles
        const data = res.data.filter(j => 
          j.jobType?.toLowerCase().includes("intern") || 
          j.category === "Government"
        );
        setJobs(data);
        setLoading(false);
      })
      .catch(err => {
        console.error("Fetch error:", err);
        setLoading(false);
      });
  };

  // API Filtering: Triggered on button click
  const applyFilter = () => {
    setLoading(true);
    const params = new URLSearchParams({
      jobType: "Internship",
      branch: branch,
      year: year,
      category: category
    });

    axios.get(`http://localhost:5000/api/jobs?${params.toString()}`)
      .then(res => {
        setJobs(res.data);
        setLoading(false);
      });
  };

  // Local UI Filtering: For instant response as user types/selects
  const filteredJobs = jobs.filter(job => {
    return (
      (year === "" || job.target_batch?.includes(year)) &&
      (branch === "" || job.eligible_branches?.includes(branch)) &&
      (category === "" || job.category === category)
    );
  });

  return (
    <div className="page">
      <header className="page-header">
        <h1>B.Tech Internship Portal</h1>
        <p>Verified opportunities from Government & Top Tech firms</p>
      </header>

      {/* Filter Section */}
      <div className="filters-bar">
        <div className="filter-item">
          <label>Target Year</label>
          <select value={year} onChange={e => setYear(e.target.value)}>
            <option value="">All Years</option>
            <option value="2025">2025 Batch</option>
            <option value="2026">2026 Batch</option>
            <option value="2027">2027 Batch</option>
          </select>
        </div>

        <div className="filter-item">
          <label>Branch</label>
          <select value={branch} onChange={e => setBranch(e.target.value)}>
            <option value="">All Branches</option>
            <option value="CSE">CSE / IT</option>
            <option value="ECE">ECE / EEE</option>
            <option value="MECH">Mechanical</option>
            <option value="CIVIL">Civil</option>
          </select>
        </div>

        <div className="filter-item">
          <label>Sector</label>
          <select value={category} onChange={e => setCategory(e.target.value)}>
            <option value="">All Sectors</option>
            <option value="Government">Government / PSU</option>
            <option value="Private">Private / Corporate</option>
          </select>
        </div>

        <button className="btn-search" onClick={applyFilter}>
          Sync with DB
        </button>
      </div>

      {/* Jobs Grid */}
      {loading ? (
        <div className="loader">Searching for opportunities...</div>
      ) : (
        <div className="jobs-grid">
          {filteredJobs.length > 0 ? (
            filteredJobs.map(job => (
              <div key={job.jobId} className={`job-card ${job.category === 'Government' ? 'govt-highlight' : ''}`}>
                {job.category === 'Government' && <span className="govt-badge">Official Govt</span>}
                
                <div className="card-body">
                  <h3 className="job-title">{job.jobTitle}</h3>
                  <h4 className="company-name">{job.companyName}</h4>
                  
                  <div className="job-tags">
                    {job.eligible_branches?.map(b => (
                      <span key={b} className="branch-tag">{b}</span>
                    ))}
                  </div>

                  <div className="job-info">
                    <span>📍 {job.location || "Remote"}</span>
                    <span>💰 {job.paid === "Yes" ? "Paid" : "Unpaid"}</span>
                  </div>
                </div>

                <div className="card-footer">
                  <span className="scraped-date">
                    Added: {new Date(job.scrapedAt || job.date).toLocaleDateString()}
                  </span>
                  <a 
                    href={job.applicationLink} 
                    target="_blank" 
                    rel="noreferrer" 
                    className="apply-link"
                  >
                    Apply Now
                  </a>
                </div>
              </div>
            ))
          ) : (
            <div className="empty-state">No matching internships found. Try adjusting filters.</div>
          )}
        </div>
      )}
    </div>
  );
}

export default Internships;
